int extract_status_code(char *buffer, size_t size)
{
	char *buf_code;
	char *begin;
	char *end = buffer + size;
	size_t inc = 0;
	int code;

	if (buffer == NULL || size == 0)
		return 0;

	/* Allocate the room */
	buf_code = (char *)MALLOC(10);
	if (buf_code == NULL)
		return 0;

	/* Status-Code extraction */
	while (buffer < end && *buffer++ != ' ') ;
	begin = buffer;
	while (buffer < end && *buffer++ != ' ')
		inc++;

	/* Copy at most 9 characters and always NUL-terminate */
	if (inc > 9)
		inc = 9;
	if (begin + inc > end)
		inc = (size_t)(end - begin);
	memcpy(buf_code, begin, inc);
	buf_code[inc] = '\0';

	code = atoi(buf_code);
	FREE(buf_code);
	return code;
}

